The violated invariant is that a block-wide barrier must be reached consistently by all participating threads in the block. With valid = 70, threads 0–69 reach __syncthreads(), while threads 70–95 skip it. That is invalid synchronization, but it does not imply every GPU must hang; the responsive host endpoint also does not establish that this stream is progressing.

Move the barrier outside the conditional and explicitly write zero when valid is zero:

```cuda
// sum.cu
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

#define CHECK(call) do {                                      \
    cudaError_t err = (call);                                 \
    if (err != cudaSuccess) {                                \
        std::fprintf(stderr, "%s: %s\n", #call,               \
                     cudaGetErrorString(err));               \
        std::exit(EXIT_FAILURE);                             \
    }                                                        \
} while (0)

__global__ void sum_valid(const float* input, float* output,
                          int valid) {
    __shared__ float values[96];
    unsigned int tid = threadIdx.x;
    values[tid] = (tid < static_cast<unsigned int>(valid))
                    ? input[tid] : 0.0f;
    __syncthreads();

    if (tid == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i)
            sum += values[i];
        *output = sum;
    }
}

int main(int argc, char** argv) {
    int valid = 70;
    if (argc > 2) return EXIT_FAILURE;
    if (argc == 2) {
        char* end = nullptr;
        long n = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' || n < 0 || n > 96) {
            std::fprintf(stderr, "valid must be 0 through 96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(n);
    }

    float input[96];
    for (int i = 0; i < 96; ++i) input[i] = 1.0f;
    float *d_input = nullptr, *d_output = nullptr;
    cudaStream_t stream;
    CHECK(cudaStreamCreate(&stream));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&d_input),
                     sizeof(input)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&d_output),
                     sizeof(float)));
    CHECK(cudaMemcpyAsync(d_input, input, sizeof(input),
                          cudaMemcpyHostToDevice, stream));

    sum_valid<<<1, 96, 0, stream>>>(d_input, d_output, valid);
    CHECK(cudaGetLastError());

    float result;
    CHECK(cudaMemcpyAsync(&result, d_output, sizeof(result),
                          cudaMemcpyDeviceToHost, stream));
    CHECK(cudaStreamSynchronize(stream));
    std::printf("sum = %g\n", result);

    CHECK(cudaFree(d_input));
    CHECK(cudaFree(d_output));
    CHECK(cudaStreamDestroy(stream));
    return EXIT_SUCCESS;
}
```

Build with `nvcc sum.cu -o sum` and run `./sum 70`. The kernel requires exactly one block of 96 threads, valid in [0, 96], an input allocation containing at least valid floats, and one writable output float.

Synchronization proof: all 96 threads write their own shared-memory slot and then reach the same unconditional barrier. Only threads with tid < valid evaluate input[tid], so no input read is out of bounds. The barrier makes those writes visible before thread zero reads entries 0 through valid − 1; no thread subsequently modifies them. At valid = 0, the loop is empty and thread zero writes 0; at valid = 96, all 96 entries are safely summed. Same-stream ordering and the successful host synchronization ensure the copied result is ready before printing. An immediate launch check alone does not prove execution completed.
